        return
    }

    foreach ($child in $children) {
        $childDepth = $Depth + 1
        $realChild = [string](Get-WReparseMemberValue -InputObject $child -Name 'FullName')
        $name = [string](Get-WReparseMemberValue -InputObject $child -Name 'Name')
        if ([string]::IsNullOrEmpty($name)) { $name = Split-Path -Leaf $realChild }
        $relative = Join-WReparseRelativePath -Prefix $RelativePrefix -Name $name

        if (Test-WReparseIsReparsePoint -Item $child) {
            $linkType = [string](Get-WReparseMemberValue -InputObject $child -Name 'LinkType')
            $rawTarget = Get-WReparseRawTarget -Item $child
            $resolved = Resolve-WReparseLinkTarget -LinkFullPath $realChild -RawTarget $rawTarget
            $inScope = $false
            if ($null -ne $resolved) {
                $inScope = Test-WReparseWithinRoot -Path $resolved -Root $State.Root
            }

            [void]$State.Records.Add((New-WReparseRecord -RelativePath $relative -Kind 'ReparsePoint' `
                -ReparseKind (Get-WReparseKindFromLinkType -LinkType $linkType) `
                -Target $rawTarget -ResolvedTarget $resolved -InScope $inScope `
                -Depth $childDepth -Size 0))

            # Default mode: register the entry, never enter the target, count
            # it as skipped. No cycle / broken_target diagnosis happens here:
            # that would require inspecting the target.
            if (-not $State.Follow) {
                $State.Skipped++
                continue
            }

            if ($null -eq $resolved) {
                Add-WReparseError -State $State -RelativePath $relative -Code 'broken_target' `
                    -Message 'The reparse target could not be resolved.'
                continue
            }
            if (-not (Test-Path -LiteralPath $resolved)) {
                Add-WReparseError -State $State -RelativePath $relative -Code 'broken_target' `
                    -Message 'The reparse target does not exist.'
                continue
            }

            # A cycle is an ancestor of THIS branch. Two sibling links to the
            # same target are not a cycle: neither appears on the other's chain.
            if (Test-WReparseAncestryContains -Ancestry $Ancestry -Candidate $resolved) {
                Add-WReparseError -State $State -RelativePath $relative -Code 'cycle' `
                    -Message 'The reparse target is an ancestor already visited on this branch.'
                continue
            }

            # A link to a file contributes the link record only: no children.
            if (Test-Path -LiteralPath $resolved -PathType Container) {
                Invoke-WReparseDescend -RealDirectory $resolved -RelativePrefix $relative `
                    -Depth $childDepth -Ancestry (@($Ancestry) + @($resolved)) -State $State
            }
            continue
        }

        $isContainer = [bool](Get-WReparseMemberValue -InputObject $child -Name 'PSIsContainer')
        $size = [long]0
        if (-not $isContainer) {
            $length = Get-WReparseMemberValue -InputObject $child -Name 'Length'
            if ($null -ne $length) { $size = [long]$length }
        }
        $kind = if ($isContainer) { 'Directory' } else { 'File' }

        # InScope is meaningful for reparse entries only; plain files and
        # directories (including hard links) always report false.
        [void]$State.Records.Add((New-WReparseRecord -RelativePath $relative -Kind $kind `
            -Depth $childDepth -Size $size))

        if ($isContainer) {
            $realChildCanonical = $realChild
            try { $realChildCanonical = Get-WReparseCanonicalPath -Path $realChild } catch { }
            Invoke-WReparseDescend -RealDirectory $realChildCanonical -RelativePrefix $relative `
                -Depth $childDepth -Ancestry (@($Ancestry) + @($realChildCanonical)) -State $State
        }
    }
}

function Invoke-WReparseWalk {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Root,
        [ValidateSet('Never', 'Always')][string]$FollowMode = 'Never',
        [int]$MaxDepth = 32
    )
    # A negative depth budget behaves exactly like 0.
    $effectiveMaxDepth = $MaxDepth
    if ($effectiveMaxDepth -lt 0) { $effectiveMaxDepth = 0 }

    $state = @{
        Records  = New-Object System.Collections.ArrayList
        Errors   = New-Object System.Collections.ArrayList
        Skipped  = 0
        Root     = $null
        Follow   = ($FollowMode -eq 'Always')
        MaxDepth = $effectiveMaxDepth
    }

    $canonicalRoot = $null
    try { $canonicalRoot = Get-WReparseCanonicalPath -Path $Root }
    catch {
        Add-WReparseError -State $state -RelativePath '.' -Code 'invalid_argument' `
            -Message 'The scan root could not be canonicalised.'
        return New-WReparseWalkResult -Root $Root -State $state -IncludeRecords $false
    }

    $state.Root = $canonicalRoot

    if (-not (Test-Path -LiteralPath $canonicalRoot)) {
        Add-WReparseError -State $state -RelativePath '.' -Code 'not_found' `
            -Message "Scan root does not exist: $canonicalRoot"
        return New-WReparseWalkResult -Root $canonicalRoot -State $state -IncludeRecords $false
    }
    if (-not (Test-Path -LiteralPath $canonicalRoot -PathType Container)) {
        Add-WReparseError -State $state -RelativePath '.' -Code 'structure' `
            -Message "Scan root is not a directory: $canonicalRoot"
        return New-WReparseWalkResult -Root $canonicalRoot -State $state -IncludeRecords $false
    }

    # The root itself produces no record; its direct children are depth 1.
    Invoke-WReparseDirectoryWalk -RealDirectory $canonicalRoot -RelativePrefix '' `
        -Depth 0 -Ancestry @($canonicalRoot) -State $state

    return New-WReparseWalkResult -Root $canonicalRoot -State $state -IncludeRecords $true
}

function New-WReparseWalkResult {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Root,
        [Parameter(Mandatory = $true)][hashtable]$State,
        [bool]$IncludeRecords = $true
    )
    $records = @()
    if ($IncludeRecords) { $records = $State.Records.ToArray() }
    return [pscustomobject]@{
        Root    = $Root
        Records = [object[]]@($records)
        Errors  = [object[]]@($State.Errors.ToArray())
        Skipped = [int]$State.Skipped
    }
}

# WReparse - path semantics
# Canonicalisation, directory-boundary containment, and link-target resolution.
# Part of the WReparse implementation. See the contract under docs/

Set-StrictMode -Version Latest

# True for a bare volume root ('C:\'), the one shape that must keep its
# trailing separator because removing it would change the meaning of the path
# ('C:' is drive-relative, not the volume root).
function Test-WReparseIsVolumeRoot {
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)][AllowEmptyString()][string]$Path)
    if ([string]::IsNullOrEmpty($Path)) { return $false }
    $normalised = $Path.Replace([char]'/', [char]'\')
    return ($normalised.Length -eq 3 -and $normalised[1] -eq [char]':' -and $normalised[2] -eq [char]'\')
}

# Canonical form used for every comparison and for the report:
#   * full (rooted) path with '.' and '..' collapsed
#   * no trailing directory separator, except for a volume root ('C:\')
#   * a UNC share root keeps its shape as '\\server\share'
#   * original casing preserved (the report echoes what the caller passed;
#     comparisons use an ordinal-ignore-case comparer instead)
function Get-WReparseCanonicalPath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Path
    )
    if ([string]::IsNullOrWhiteSpace($Path)) {
        throw [System.ArgumentException]::new('Path must not be empty.', 'Path')
    }

    $full = [System.IO.Path]::GetFullPath($Path)
    if (Test-WReparseIsVolumeRoot -Path $full) { return $full }

    $trimmed = $full.TrimEnd([char]'\', [char]'/')
    if ([string]::IsNullOrEmpty($trimmed)) { return $full }

    # '\\' alone is not a usable path; hand back what the BCL produced.
    if ($trimmed -eq '\\' -or $trimmed -eq '//') { return $full }

    # 'C:' alone is drive-relative; restore the volume root form.
    if ($trimmed.Length -eq 2 -and $trimmed[1] -eq [char]':') { return $trimmed + '\' }

    return $trimmed
}

# Directory-boundary aware containment. 'C:\root2' is NOT inside 'C:\root'
# even though 'C:\root2'.StartsWith('C:\root') is true. Windows path
# comparison is case-insensitive, so the ordinal-ignore-case comparer is used.
function Test-WReparseWithinRoot {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Path,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Root
    )
    if ([string]::IsNullOrWhiteSpace($Path) -or [string]::IsNullOrWhiteSpace($Root)) {
        return $false
    }
    $p = $null
    $r = $null
    try {
        $p = Get-WReparseCanonicalPath -Path $Path
        $r = Get-WReparseCanonicalPath -Path $Root
    }
    catch {
        return $false
    }

    # The root itself counts as inside.
    if ([System.StringComparer]::OrdinalIgnoreCase.Equals($p, $r)) { return $true }

    # Compare against the root plus a separator so only whole path segments
    # match: 'C:\root\' prefixes 'C:\root\a' but not 'C:\root2'.
    $prefix = $r
    if (-not $prefix.EndsWith('\')) { $prefix = $prefix + '\' }
    return $p.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)
}

# Relative path of a scanned entry with respect to the scan root, using the
# Windows separator. The root itself yields '.'.
function Get-WReparseRelativePath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][string]$FullPath,
        [Parameter(Mandatory = $true)][string]$Root
    )
    $p = Get-WReparseCanonicalPath -Path $FullPath
    $r = Get-WReparseCanonicalPath -Path $Root
    if ([System.StringComparer]::OrdinalIgnoreCase.Equals($p, $r)) { return '.' }
    $prefix = $r
    if (-not $prefix.EndsWith('\')) { $prefix = $prefix + '\' }
    if ($p.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $p.Substring($prefix.Length)
    }
    return $p
}

# The reparse target stored on disk may be relative. A relative target is
# resolved against the directory that CONTAINS the link, never against the
# process working directory and never against the scan root.
function Resolve-WReparseLinkTarget {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][AllowNull()][string]$LinkFullPath,
        [Parameter(Mandatory = $false)][AllowEmptyString()][AllowNull()][string]$RawTarget
    )
    if ([string]::IsNullOrWhiteSpace($RawTarget)) { return $null }

    $target = $RawTarget
    # Junction targets are sometimes reported in NT object-manager form.
    if ($target.StartsWith('\??\')) { $target = $target.Substring(4) }
    if ([string]::IsNullOrWhiteSpace($target)) { return $null }

    try {
        if ([System.IO.Path]::IsPathRooted($target)) {
            return Get-WReparseCanonicalPath -Path $target
        }

        if ([string]::IsNullOrWhiteSpace($LinkFullPath)) { return $null }

        # Anchor on the directory holding the link, not on the process CWD.
        $linkCanonical = Get-WReparseCanonicalPath -Path $LinkFullPath
        $linkDirectory = [System.IO.Path]::GetDirectoryName($linkCanonical)
        if ([string]::IsNullOrWhiteSpace($linkDirectory)) { return $null }

        $combined = [System.IO.Path]::Combine($linkDirectory, $target)
        return Get-WReparseCanonicalPath -Path $combined
    }
    catch {
        return $null
    }
}

# Stable ordering key: ordinal, case-insensitive first, with a case-sensitive
# tie-break so two entries whose names differ only by case keep a
# deterministic position. Ordinal comparison keeps the order independent of
# the host culture: 'Z' (U+005A) sorts before 'Ä' (U+00C4) and 'ö' (U+00F6).
function Compare-WReparsePath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Left,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Right
    )
    $primary = [System.StringComparer]::OrdinalIgnoreCase.Compare($Left, $Right)
    if ($primary -ne 0) { return $primary }
    return [System.StringComparer]::Ordinal.Compare($Left, $Right)
}

